import{_ as a,o as t,c as r,a5 as i}from"./chunks/framework.bIR-4glx.js";const _=JSON.parse('{"title":"十年前的博客归档","description":"从 2016 年旧博客快照恢复的四篇完整文章，作为历史个人记录保存，而不是当前建议。","frontmatter":{"title":"十年前的博客归档","description":"从 2016 年旧博客快照恢复的四篇完整文章，作为历史个人记录保存，而不是当前建议。","updated":"2026-08-31T00:00:00.000Z"},"headers":[],"relativePath":"threads/archive/index.md","filePath":"threads/archive/README.md","lastUpdated":1788134400000}'),l={name:"threads/archive/index.md"};function o(c,e,d,n,s,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="十年前的博客归档" tabindex="-1">十年前的博客归档 <a class="header-anchor" href="#十年前的博客归档" aria-label="Permalink to &quot;十年前的博客归档&quot;">​</a></h1><p>这里收录的是从 Web Archive 恢复出的 <code>zb.gs</code> 旧博客内容。</p><p>这些文字写在更早的阶段：有写作梦被打断后的倔强，有大四之后重新折腾事业的热气，也有对社会议题和个人选择的朴素判断。把它们放回这份指南里，是为了让“人生进阶”不只停留在方法论上，也能看见一个人一路走来的原始切片。</p><p>本次根据可访问的 Wayback Machine 快照与文章互链，共整理出 4 篇旧文：</p><ul><li>2016-04-23：<a href="./a-place-to-write">终于有了一个写字的地方</a></li><li>2016-04-24：<a href="./last-year-and-now">简单介绍下去年和现在的我</a></li><li>2016-04-24：<a href="./help-the-elderly">到底该不该扶老人</a></li><li>2016-05-21：<a href="./blog-renaming-notice">博客临时更名公告</a></li></ul><blockquote><p>说明：原站点部分 Archive 索引接口访问不稳定；本文日期按当前可恢复的 Wayback 快照标注。本归档优先保存已能从入口页与文章近期列表中恢复的正文和评论。后续如果发现更多旧文，可以继续按这个目录结构补进来。</p></blockquote>',6)])])}const f=a(l,[["render",o]]);export{_ as __pageData,f as default};
